use super::*;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn adv_t<const N:usize>(h:&mut Harness,o:&mut RetainedDiagnosticPreparation<N>,t:[RetainedDiagnosticTarget<'_>;N],body:usize,max:u64,g:RetainedCloneGrant)->Recorded{h.turn(g,max,&mut|e,r,rec|if rec{o.recover_advance_targets_into(t,body,max,e,r)}else{o.advance_targets_into(t,body,max,e,r)})}
fn adv<const N:usize>(h:&mut Harness,o:&mut RetainedDiagnosticPreparation<N>,t:[RetainedCloneRef<'_,String>;N],body:usize,max:u64,g:RetainedCloneGrant)->Recorded{h.turn(g,max,&mut|e,r,rec|if rec{o.recover_advance_into(t,body,max,e,r)}else{o.advance_into(t,body,max,e,r)})}
fn shut<const N:usize>(h:&mut Harness,o:&mut RetainedDiagnosticPreparation<N>,g:RetainedCloneGrant)->Recorded{let units=o.close_work_demand(4096).unwrap();h.turn(g,units,&mut|e,r,rec|if rec{o.recover_close_into(4096,e,r)}else{o.close_into(4096,e,r)})}
#[test]
fn original_unsigned_diagnostic_targets_preserve_source_binding_and_paid_decimal_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){let mut hn=Harness::new();let original=hn.source(case["value"].as_u64().unwrap()as u32);let foreign=hn.source(case["value"].as_u64().unwrap()as u32);let target=[RetainedDiagnosticTarget::Unsigned(original.borrow())];for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=RetainedDiagnosticPreparation::<1>::default();owner.start(RetainedDiagnosticSpec{level:Severity::Error,code:"mutation.target-missing",message:"The addressed entity is missing."},grant(RetainedDiagnosticPreparation::<1>::start_demand())).unwrap();let mut done=false;let mut turns=0;let mut saw_foreign=false;while cut.is_none_or(|cut|turns<cut){let d=owner.target_demand(target,4096,4096).unwrap();let g=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_release_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{if retained_mutation_demand_fits(d,denied){continue;}let r=adv_t(&mut hn,&mut owner,target,4096,4096,denied);assert_eq!(r.result.unwrap().progress(),Default::default());assert_eq!(r.heap,(0,0));assert_eq!(owner.target_demand(target,4096,4096).unwrap(),d);}let r=adv_t(&mut hn,&mut owner,target,4096,4096,g);let hp=r.heap;let s=r.result.unwrap();assert!(s.progress().fits(g));assert_eq!(hp,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;saw_foreign|=owner.target_demand([RetainedDiagnosticTarget::Unsigned(foreign.borrow())],4096,4096).is_err();if matches!(s,RetainedCloneStep::Complete(_)){done=true;break;}assert!(turns<1000);}if cut.is_none(){assert!(done&&saw_foreign);let g=grant(RetirementDemand{copy_bytes:size_of::<Vec<MutationMessage>>(),depth:1,..Default::default()});let(rows,p)=owner.take(g).result.unwrap().unwrap();assert!(p.fits(g));assert_eq!(rows[0].target,[case["target"].as_str().unwrap()]);let mut ledger=MutationMessageLedgerRetirement::new(String::new(),rows);while !ledger.terminal_is_empty(){let d=RetirementDemand{copy_bytes:ledger.next_copy_byte_demand(),capacity_bytes:ledger.next_capacity_byte_demand(4096).unwrap(),release_bytes:ledger.next_release_byte_demand().unwrap(),depth:ledger.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||ledger.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}}
 owner.begin_close();for _ in 0..10000{if owner.terminal_is_empty(){break;}let g=grant(owner.close_demand(4096).unwrap());let r=shut(&mut hn,&mut owner,g);let h=r.heap;let s=r.result.unwrap();assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}
 hn.close_source(original);hn.close_source(foreign);
 }
}
